class ValidateQueryToolInput(BaseModel):
    query: Annotated[str, "the query you want to validate."]


class ValidateQueryTool(BaseTool):
    name = "ValidateQueryTool"
    description = "Use this to validate a generated query is valid promQL syntax."
    user: auth_schemas.User = None
    context: ContextManager = None
    args_schema: Type[BaseModel] = ValidateQueryToolInput

    def __init__(self, user: auth_schemas.User, context: ContextManager):
        super().__init__()
        self.user = user
        self.context = context

    def _run(self, input: str):
        return "Does not support sync"

    async def _arun(self, query: str):
        url = settings.prometheus_url + "/api/v1/query"
        timeout = httpx.Timeout(10.0, read=15.0)
        async with httpx.AsyncClient(timeout=timeout) as client:
            response = await client.get(
                url,
                headers={"X-Scope-OrgID": self.user.account_id},
                params={"query": query},
            )

            if response.status_code == 400:
                try:
                    data = response.json()
                    error = data.get("error")
                    return str(error) if error else "invalid promQL"
                except Exception as e:
                    logger.warning(
                        f"Unable to get prometheus response for query {query}."
                        f" Caught exception: {e}"
                    )
                    return (
                        f"Unable to get prometheus response for query {query}."
                        f" Caught exception: {e}"
                    )
            elif response.status_code != 200:
                return (
                    f"Got status code {response.status_code} when attempting to"
                    f" validate query: {query}"
                )

        try:
            self.context.update_query_params(query_string=query, validated=True)
        except QueryDoesNotExistError:
            return (
                "promQL is valid but the query has not been created, please create the"
                " query then revalidate it"
            )

        return f"promQL is valid for query {query}"
```

